)

type aggregateSnapshot struct {
	TotalThreats       int            `json:"total_threats"`
	ActiveCampaigns    int            `json:"active_campaigns"`
	MeanEnrichedRisk   float64        `json:"mean_enriched_risk"`
	DominantThreatType string         `json:"dominant_threat_type"`
	ActorThreatCounts  map[string]int `json:"actor_threat_counts"`
}

type aggregateReport struct {
	SnapshotCount       int            `json:"snapshot_count"`
	TotalThreats        int            `json:"total_threats"`
	TotalCampaigns      int            `json:"total_campaigns"`
	GlobalMeanRisk      float64        `json:"global_mean_risk"`
	GlobalMaxMeanRisk   float64        `json:"global_max_mean_risk"`
	GlobalRiskCategory  string         `json:"global_risk_category"`
	CombinedActorCounts map[string]int `json:"combined_actor_counts"`
	TopActor            string         `json:"top_actor"`
	DominantThreatType  string         `json:"dominant_threat_type"`
	TypeCounts          map[string]int `json:"type_counts"`
}

func runAggregate(args []string) int {
	report := aggregateReport{
		CombinedActorCounts: map[string]int{},
		TypeCounts:          map[string]int{},
	}

	reader := bufio.NewReader(os.Stdin)
	weightedRiskSum := 0.0
	maxMeanRisk := 0.0
	dominantTypeCounts := map[string]int{}
	actorCounts := map[string]int{}
	snapshotCount := 0

	for {
		line, err := reader.ReadString('\n')
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			if err == io.EOF {
				break
			}
			continue
		}

		var snap aggregateSnapshot
		if jerr := json.Unmarshal([]byte(trimmed), &snap); jerr != nil {
			fmt.Fprintln(os.Stderr, "error: malformed JSON input:", jerr)
			return 2
		}

		snapshotCount++
		report.TotalThreats += snap.TotalThreats
		report.TotalCampaigns += snap.ActiveCampaigns
		weightedRiskSum += snap.MeanEnrichedRisk * float64(snap.TotalThreats)
		if snap.MeanEnrichedRisk > maxMeanRisk {
			maxMeanRisk = snap.MeanEnrichedRisk
		}
		for actor, count := range snap.ActorThreatCounts {
			actorCounts[actor] += count
		}
		dominantType := snap.DominantThreatType
		dominantTypeCounts[dominantType]++
		report.TypeCounts[dominantType] += snap.TotalThreats

		if err == io.EOF {
			break
		}
	}

	report.SnapshotCount = snapshotCount
	if report.TotalThreats > 0 {
		report.GlobalMeanRisk = round2(weightedRiskSum / float64(report.TotalThreats))
	} else {
		report.GlobalMeanRisk = 0.0
	}
	report.GlobalMaxMeanRisk = round2(maxMeanRisk)
	report.GlobalRiskCategory = snapshotRiskCategory(report.GlobalMeanRisk)
	report.CombinedActorCounts = actorCounts
	report.TopActor = topActorFromCounts(actorCounts)
	report.DominantThreatType = topDominantType(dominantTypeCounts)

	if report.CombinedActorCounts == nil {
		report.CombinedActorCounts = map[string]int{}
	}
	if report.TypeCounts == nil {
		report.TypeCounts = map[string]int{}
	}

	out, err := json.Marshal(report)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error: encoding aggregate report:", err)
		return 1
	}
	fmt.Println(string(out))
	return 0
}

func topActorFromCounts(counts map[string]int) string {
	actors := make([]string, 0, len(counts))
	for actor := range counts {
		actors = append(actors, actor)
	}
	sort.Strings(actors)

	topActor := ""
	maxCount := -1
	for _, actor := range actors {
		count := counts[actor]
		if count > maxCount {
			maxCount = count
			topActor = actor
		}
	}
	if maxCount < 0 {
		return ""
	}
	return topActor
}

func topDominantType(counts map[string]int) string {
	types := make([]string, 0, len(counts))
	for t := range counts {
		types = append(types, t)
	}
	sort.Strings(types)

	topType := ""
	maxCount := -1
	for _, t := range types {
		count := counts[t]
		if count > maxCount {
			maxCount = count
			topType = t
		}
	}
	if maxCount < 0 {
		return ""
	}
	return topType
}
